impl<T: crate::Float> MassConcentration<T> {
    /// The value in the largest SI-prefixed form of the base unit that doesn't
    /// exceed it, in steps of 1000 (`µg/m³`, `mg/m³`, `g/m³`, `kg/m³`).
    /// Zero, NaN and infinities stay in the base unit.
    #[inline]
    pub fn auto_unit(self) -> crate::InUnit<T, MassConcentrationUnit> {
        const SCALE: [(f64, MassConcentrationUnit); 4] = [
            (1.0, MassConcentrationUnit::KilogramPerCubicMeter),
            (0.001, MassConcentrationUnit::GramPerCubicMeter),
            (1e-6, MassConcentrationUnit::MilligramPerCubicMeter),
            (1e-9, MassConcentrationUnit::MicrogramPerCubicMeter),
        ];
        let magnitude = self.0.abs();
        if magnitude == T::from_f64(0.0) || !magnitude.is_finite() {
            return self.in_unit(MassConcentrationUnit::KilogramPerCubicMeter);
        }
        let mut unit = SCALE[SCALE.len() - 1].1;
        for (factor, candidate) in SCALE {
            if magnitude >= T::from_f64(factor) {
                unit = candidate;
                break;
            }
        }
        self.in_unit(unit)
    }
}

